/* SBR-53b: real QMF analysis and slot-owned HF baseline bridge.
 * No HE-AAC PCM is generated by this test. */
#include "sauti_aac_sbr_temporal_qmf.h"
#include "sauti_aac_sbr_master.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>

static void make_frame(SautiAacSbrPayloadFrame *f){
    SautiAacSbrMaster master;
    memset(f,0,sizeof(*f));
    assert(sauti_aac_sbr_master_linear(16u,32u,1u,0u,&master));
    assert(sauti_aac_sbr_tables_build(&master,2u,&f->tables));
    assert(sauti_aac_sbr_patch_build(48000u,&master,
                                    &f->tables,&f->patches));
    f->grid.env_count=1u;
    f->grid.noise_count=1u;
    f->grid.env_border[0]=0u;f->grid.env_border[1]=16u;
    f->grid.noise_border[0]=0u;f->grid.noise_border[1]=16u;
    f->energy.env_count=1u;
    f->energy.noise_count=1u;
    f->energy.freq_res[0]=1u;
    f->env_edges[0]=0u;f->env_edges[1]=32u;
    f->noise_edges[0]=0u;f->noise_edges[1]=32u;
    f->limiter_mode=2u;f->gain_mode=2u;
    for(unsigned b=0u;b<f->tables.n_high;b++)
        f->energy.env_energy[0][b]=100.0+(double)b;
    for(unsigned b=0u;b<f->tables.n_noise;b++)
        f->energy.noise_factor[0][b]=0.25+(double)b;
}
static void pcm_fill(float out[1024],unsigned shift){
    for(unsigned i=0u;i<1024u;i++){
        const int x=(int)((i*7u+shift*13u)%127u)-63;
        out[i]=(float)x/512.0f;
    }
}
int main(void){
    SautiAacSbrPayloadFrame plain,prior,current;
    make_frame(&plain);
    prior=plain;
    prior.grid.env_border[1]=17u;
    prior.grid.noise_border[1]=17u;
    prior.env_edges[1]=34u;
    prior.noise_edges[1]=34u;
    current=plain;
    current.grid.env_border[0]=1u;
    current.grid.noise_border[0]=1u;
    current.env_edges[0]=2u;
    current.noise_edges[0]=2u;

    SautiAacSbrTemporalHandoff handoff;
    SautiAacSbrTemporalHistory first={0},joined={0};
    assert(sauti_aac_sbr_temporal_history_push(
           &plain,&first,&handoff));
    assert(sauti_aac_sbr_temporal_history_push(
           &prior,&joined,&handoff));
    assert(sauti_aac_sbr_temporal_history_push(
           &current,&joined,&handoff));
    assert(handoff.previous_tail_slots==2u &&
           handoff.current_start_slots==2u &&
           handoff.overlapping_slots==0u);
    SautiAacSbrResolvedFrame owners;
    assert(sauti_aac_sbr_temporal_resolve(&joined,&owners));
    assert(owners.previous_slots==2u);

    float pcm[1024];
    SautiAacSbrQmfAnalysisState state={0};
    SautiAacSbrComplex low[1024],hf[2048];
    pcm_fill(pcm,0u);
    assert(sauti_aac_sbr_temporal_qmf_prepare(
        &first,pcm,1024u,&state,low,1024u,hf,2048u));
    assert(state.ready==1u && state.samples_consumed==1024u);
    SautiAacSbrQmfAnalysisState warm=state;

    pcm_fill(pcm,1u);
    SautiAacSbrQmfAnalysisState manual=warm;
    SautiAacSbrComplex reference_low[1024],reference_hf[2048];
    assert(sauti_aac_sbr_qmf_analyze_32(
        pcm,1024u,32u,32u,reference_low,1024u,&manual));
    for(unsigned slot=0u;slot<32u;slot++){
        const SautiAacSbrPayloadFrame *f=
            owners.slot[slot].source==0u?&joined.previous:&joined.current;
        assert(sauti_aac_sbr_hf_transpose(
            &f->patches,&f->tables,
            reference_low+(size_t)slot*32u,32u,1u,
            reference_hf+(size_t)slot*64u,64u));
    }
    assert(sauti_aac_sbr_temporal_qmf_prepare(
        &joined,pcm,1024u,&state,low,1024u,hf,2048u));
    assert(state.samples_consumed==2048u);
    assert(memcmp(&state,&manual,sizeof(state))==0);
    assert(memcmp(low,reference_low,sizeof(low))==0);
    assert(memcmp(hf,reference_hf,sizeof(hf))==0);
    puts("SBR-53b: 32-slot continuous QMF analysis with prior/current HF patch owners PASS");

    SautiAacSbrQmfAnalysisState saved_state=state;
    SautiAacSbrComplex saved_low[1024],saved_hf[2048];
    memcpy(saved_low,low,sizeof(low));
    memcpy(saved_hf,hf,sizeof(hf));
    SautiAacSbrTemporalHistory broken=joined;
    broken.previous.patches.source_for_target[broken.previous.tables.kx]=-1;
    assert(!sauti_aac_sbr_temporal_qmf_prepare(
        &broken,pcm,1024u,&state,low,1024u,hf,2048u));
    assert(memcmp(&state,&saved_state,sizeof(state))==0);
    assert(memcmp(low,saved_low,sizeof(low))==0);
    assert(memcmp(hf,saved_hf,sizeof(hf))==0);
    broken=joined;
    broken.current.energy.env_energy[0][0]=NAN;
    assert(!sauti_aac_sbr_temporal_qmf_prepare(
        &broken,pcm,1024u,&state,low,1024u,hf,2048u));
    assert(memcmp(&state,&saved_state,sizeof(state))==0);
    assert(memcmp(low,saved_low,sizeof(low))==0);
    assert(memcmp(hf,saved_hf,sizeof(hf))==0);
    pcm[1000]=NAN; /* late AAC core input failure */
    assert(!sauti_aac_sbr_temporal_qmf_prepare(
        &joined,pcm,1024u,&state,low,1024u,hf,2048u));
    assert(memcmp(&state,&saved_state,sizeof(state))==0);
    assert(memcmp(low,saved_low,sizeof(low))==0);
    assert(memcmp(hf,saved_hf,sizeof(hf))==0);
    puts("SBR-53b: malformed prior HF map, invalid energy, late NaN QMF -> atomic rollback PASS");
    return 0;
}
